from __future__ import annotations

from pymatgen.symmetry.maggroups import MagneticSpaceGroup
from pymatgen.symmetry.settings import JonesFaithfulTransformation


class MagneticCifBlock:
    def __init__(self, data):
        self.data = dict(data)


class CifParser:
    """Retained magnetic-CIF operation reader for the task snapshot."""

    def get_magsymops(self, data):
        try:
            # Get bns_number
            if data.data.get("_space_group_magn.number_BNS"):
                group_id = list(map(int, data.data["_space_group_magn.number_BNS"].split(".")))
            else:
                group_id = list(map(int, data.data["_space_group_magn.number_BNS_id"].split(".")))

            # Get transformation information (if available)
            transformation = None
            if data.data.get("_space_group_magn.transform_BNS_Pp_abc"):
                transformation = data.data["_space_group_magn.transform_BNS_Pp_abc"]

            # Get space group
            symops = MagneticSpaceGroup(group_id).symmetry_ops

            # Transform the standard BNS operators into the producer's
            # coordinate convention so archived records retain their
            # scientific operation semantics in the coordinates they
            # were supplied in.
            if transformation is not None:
                jft = JonesFaithfulTransformation.from_transformation_string(transformation)
                symops = [jft.transform_symmop(op) for op in symops]

            return symops
        except Exception as e:
            return e

